using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Variante direccional de la skill de vapor industrial.
/// Hereda de IndustrialFogCar pero ignora su punto único de spawn.
/// - Define dos empties: forwardSpawn y backwardSpawn.
/// - En OnProbabilitySuccess detecta hornos (Furnace / HeatSphere) cercanos.
/// - Si los hornos más cercanos están mayormente detrás del coche => instancia atrás; si no => adelante.
/// - Instancia un prefab grande de vapor (steamPrefab).
/// - El prefab debe incluir un collider (trigger) con el script SteamHeatDisabler para afectar hornos.
/// </summary>
public class IndustrialDirectionalSteamCar : IndustrialFogCar
{
    [Header("Directional Steam Settings")] 
    [Tooltip("Spawn point delantero.")] [SerializeField] private Transform forwardSpawn;
    [Tooltip("Spawn point trasero.")] [SerializeField] private Transform backwardSpawn;
    [Tooltip("Prefab del gran vapor direccional.")] [SerializeField] private GameObject steamPrefab;
    [Tooltip("Radio de búsqueda para localizar hornos / fuentes de calor.")] [SerializeField] private float furnaceSearchRadius = 25f;
    [Tooltip("Capas consideradas para la búsqueda de hornos.")] [SerializeField] private LayerMask furnaceLayerMask;
    [Tooltip("Cuántos colliders máximos evaluar por barrido.")] [SerializeField] private int maxFurnaceColliders = 32;
    [Tooltip("Mantener el vapor parentado al spawn elegido.")] [SerializeField] private bool parentSteam = true;
    [Tooltip("Destruir automáticamente el vapor tras esta duración (0 = infinito hasta que el prefab se auto-destruya)." )]
    [SerializeField] private float autoDestroyAfter = 8f;

    [Header("Debug")] 
    [SerializeField] private bool debugLogs = false;
    [SerializeField] private Color searchGizmoColor = new Color(1f,0.8f,0.4f,0.15f);

    private readonly Collider[] _overlapResults = new Collider[64];
    private GameObject activeSteamInstance;

    protected override void OnProbabilitySuccess(Collider col, GameObject spawnedInstance)
    {
        // Ignoramos la lógica de IndustrialFogCar y aplicamos la propia direccional.
        SpawnDirectionalSteam();
    }

    private void SpawnDirectionalSteam()
    {
        if (steamPrefab == null)
        {
            if (debugLogs) Debug.LogWarning("[IndustrialDirectionalSteamCar] No hay steamPrefab asignado.", this);
            return;
        }
        if (!forwardSpawn || !backwardSpawn)
        {
            if (debugLogs) Debug.LogWarning("[IndustrialDirectionalSteamCar] Falta asignar forwardSpawn o backwardSpawn.", this);
            return;
        }

        // Buscar hornos cercanos.
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, furnaceSearchRadius, _overlapResults, furnaceLayerMask, QueryTriggerInteraction.Collide);
        if (debugLogs) Debug.Log($"[IndustrialDirectionalSteamCar] Hornos detectados: {count}", this);

        int forwardVotes = 0;
        int backwardVotes = 0;

        Vector3 fwd = transform.forward;
        for (int i = 0; i < count && i < maxFurnaceColliders; i++)
        {
            var c = _overlapResults[i];
            if (c == null) continue;
            // Considerar objeto que tenga Furnace o HeatSphere
            bool isFurnace = c.GetComponentInParent<Furnace>() != null || c.GetComponentInParent<HeatSphere>() != null;
            if (!isFurnace) continue;
            Vector3 dir = (c.transform.position - center).normalized;
            float dot = Vector3.Dot(fwd, dir); // >0 delante, <0 detrás
            if (dot >= 0f) forwardVotes++; else backwardVotes++;
        }

        // Decidir spawn
        Transform chosen = forwardSpawn;
        if (backwardVotes > forwardVotes) chosen = backwardSpawn;

        if (activeSteamInstance != null)
        {
            Destroy(activeSteamInstance);
            activeSteamInstance = null;
        }

        activeSteamInstance = Instantiate(steamPrefab, chosen.position, chosen.rotation);
        if (parentSteam && activeSteamInstance) activeSteamInstance.transform.SetParent(chosen, true);

        if (debugLogs)
        {
            Debug.Log($"[IndustrialDirectionalSteamCar] Vapor instanciado en {(chosen == forwardSpawn ? "DELANTE" : "ATRÁS")} (FwdVotes={forwardVotes} / BackVotes={backwardVotes}).", this);
        }

        if (autoDestroyAfter > 0f && activeSteamInstance != null)
        {
            Destroy(activeSteamInstance, autoDestroyAfter);
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = searchGizmoColor;
        Gizmos.DrawSphere(transform.position, furnaceSearchRadius);
        if (forwardSpawn)
        {
            Gizmos.color = Color.green; Gizmos.DrawWireCube(forwardSpawn.position, Vector3.one * 0.5f);
        }
        if (backwardSpawn)
        {
            Gizmos.color = Color.red; Gizmos.DrawWireCube(backwardSpawn.position, Vector3.one * 0.5f);
        }
    }
#endif
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Serialization;

/// <summary>
/// Variante direccional de la skill de vapor industrial.
/// Hereda de IndustrialFogCar pero ignora su punto único de spawn.
/// - Define dos empties: forwardSpawn y backwardSpawn.
/// - En OnProbabilitySuccess detecta hornos (Furnace / HeatSphere) cercanos.
/// - Si los hornos más cercanos están mayormente detrás del coche => instancia atrás; si no => adelante.
/// - Instancia un prefab grande de vapor (steamPrefab).
/// - El prefab debe incluir un collider (trigger) con el script SteamHeatDisabler para afectar hornos.
/// </summary>
public class IndustrialDirectionalSteamCar : IndustrialFogCar
{
    [Header("Directional Steam Settings")] 
    [Tooltip("Spawn point delantero.")] [SerializeField] private Transform forwardSpawn;
    [Tooltip("Spawn point trasero.")] [SerializeField] private Transform backwardSpawn;
    [Tooltip("Prefab del gran vapor direccional.")] [SerializeField] private GameObject steamPrefab;
    [Tooltip("Radio de búsqueda para localizar hornos / fuentes de calor.")] [SerializeField] private float furnaceSearchRadius = 25f;
    [Tooltip("Capas consideradas para la búsqueda de hornos.")] [SerializeField] private LayerMask furnaceLayerMask;
    [Tooltip("Cuántos colliders máximos evaluar por barrido.")] [SerializeField] private int maxFurnaceColliders = 32;
    [Tooltip("Mantener el vapor parentado al spawn elegido.")] [SerializeField] private bool parentSteam = true;
    [Tooltip("Destruir automáticamente el vapor tras esta duración (0 = infinito hasta que el prefab se auto-destruya)." )]
    [SerializeField] private float autoDestroyAfter = 8f;

    [Header("Debug")] 
    [FormerlySerializedAs("debugLogs")]
    [SerializeField] private bool debugLogsDirectional = false;
    [SerializeField] private Color searchGizmoColor = new Color(1f,0.8f,0.4f,0.15f);

    private readonly Collider[] _overlapResults = new Collider[64];
    private GameObject activeSteamInstance;

    protected override void OnProbabilitySuccess(Collider col, GameObject spawnedInstance)
    {
        // Ignoramos la lógica de IndustrialFogCar y aplicamos la propia direccional.
        SpawnDirectionalSteam();
    }

    private void SpawnDirectionalSteam()
    {
        if (steamPrefab == null)
        {
            if (debugLogsDirectional) Debug.LogWarning("[IndustrialDirectionalSteamCar] No hay steamPrefab asignado.", this);
            return;
        }
        if (!forwardSpawn || !backwardSpawn)
        {
            if (debugLogsDirectional) Debug.LogWarning("[IndustrialDirectionalSteamCar] Falta asignar forwardSpawn o backwardSpawn.", this);
            return;
        }

        // Buscar hornos cercanos.
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, furnaceSearchRadius, _overlapResults, furnaceLayerMask, QueryTriggerInteraction.Collide);
        if (debugLogsDirectional) Debug.Log($"[IndustrialDirectionalSteamCar] Hornos detectados: {count}", this);

        int forwardVotes = 0;
        int backwardVotes = 0;

        Vector3 fwd = transform.forward;
        for (int i = 0; i < count && i < maxFurnaceColliders; i++)
        {
            var c = _overlapResults[i];
            if (c == null) continue;
            // Considerar objeto que tenga Furnace o HeatSphere
            bool isFurnace = c.GetComponentInParent<Furnace>() != null || c.GetComponentInParent<HeatSphere>() != null;
            if (!isFurnace) continue;
            Vector3 dir = (c.transform.position - center).normalized;
            float dot = Vector3.Dot(fwd, dir); // >0 delante, <0 detrás
            if (dot >= 0f) forwardVotes++; else backwardVotes++;
        }

        // Decidir spawn
        Transform chosen = forwardSpawn;
        if (backwardVotes > forwardVotes) chosen = backwardSpawn;

        if (activeSteamInstance != null)
        {
            Destroy(activeSteamInstance);
            activeSteamInstance = null;
        }

        activeSteamInstance = Instantiate(steamPrefab, chosen.position, chosen.rotation);
        if (parentSteam && activeSteamInstance) activeSteamInstance.transform.SetParent(chosen, true);

        if (debugLogsDirectional)
        {
            Debug.Log($"[IndustrialDirectionalSteamCar] Vapor instanciado en {(chosen == forwardSpawn ? "DELANTE" : "ATRÁS")} (FwdVotes={forwardVotes} / BackVotes={backwardVotes}).", this);
        }

        if (autoDestroyAfter > 0f && activeSteamInstance != null)
        {
            Destroy(activeSteamInstance, autoDestroyAfter);
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = searchGizmoColor;
        Gizmos.DrawSphere(transform.position, furnaceSearchRadius);
        if (forwardSpawn)
        {
            Gizmos.color = Color.green; Gizmos.DrawWireCube(forwardSpawn.position, Vector3.one * 0.5f);
        }
        if (backwardSpawn)
        {
            Gizmos.color = Color.red; Gizmos.DrawWireCube(backwardSpawn.position, Vector3.one * 0.5f);
        }
    }
#endif
}

using UnityEngine;
using UnityEngine.InputSystem;
using System.Collections.Generic;

public class InputDeviceManager : MonoBehaviour
{
    [SerializeField] private PlayerInput player1;
    [SerializeField] private PlayerInput player2;

    private Gamepad player1Gamepad = null;
    private Gamepad player2Gamepad = null;

    private HashSet<InputDevice> player1Devices = new HashSet<InputDevice>();
    private HashSet<InputDevice> player2Devices = new HashSet<InputDevice>();

    private Player player1Script;
    private Player player2Script;

    void Awake()
    {
        // Crear instancias separadas de ActionAssets
        player1.actions = Instantiate(player1.actions);
        player2.actions = Instantiate(player2.actions);

        player1Script = player1.GetComponent<Player>();
        player2Script = player2.GetComponent<Player>();

        // Deshabilitar el auto-switching
        player1.neverAutoSwitchControlSchemes = true;
        player2.neverAutoSwitchControlSchemes = true;

        // Asignar dispositivos iniciales
        if (Keyboard.current != null)
        {
            player1Devices.Add(Keyboard.current);
        }

        if (Gamepad.all.Count > 0)
        {
            player2Gamepad = Gamepad.all[0];
            player2Devices.Add(player2Gamepad);
            player2Devices.Add(Keyboard.current);
        }
        if (Gamepad.all.Count > 1)
        {
            player1Gamepad = Gamepad.all[1];
            player1Devices.Add(player1Gamepad);
        }

        // Configurar filtros de dispositivos
        SetupDeviceFilters();

        // Set initial UI types
        player1Script.SetUIType(player1Gamepad != null);
        player2Script.SetUIType(player2Gamepad != null);

        // Habilitar acciones
        player1.actions.Enable();
        player2.actions.Enable();

        // Suscribirse a cambios de dispositivos
        InputSystem.onDeviceChange += OnDeviceChange;
    }

    private void SetupDeviceFilters()
    {
        // Convertir HashSet a lista para Player1
        var p1DeviceList = new List<InputDevice>(player1Devices);
        if (p1DeviceList.Count > 0)
        {
            player1.actions.devices = new UnityEngine.InputSystem.Utilities.ReadOnlyArray<InputDevice>(p1DeviceList.ToArray());
        }

        // Convertir HashSet a lista para Player2
        var p2DeviceList = new List<InputDevice>(player2Devices);
        if (p2DeviceList.Count > 0)
        {
            player2.actions.devices = new UnityEngine.InputSystem.Utilities.ReadOnlyArray<InputDevice>(p2DeviceList.ToArray());
        }

        Debug.Log($"Player1 devices: {player1Devices.Count}");
        Debug.Log($"Player2 devices: {player2Devices.Count}");
    }

    private void OnDeviceChange(InputDevice device, InputDeviceChange change)
    {
        if (!(device is Gamepad newGamepad))
            return;

        switch (change)
        {
            case InputDeviceChange.Added:
            case InputDeviceChange.Reconnected:
                // Si es el gamepad de Player2
                if (player2Gamepad != null && AreGamepadsSame(newGamepad, player2Gamepad))
                {
                    player2Gamepad = newGamepad;
                    player2Devices.Remove(device); // Remover versión vieja
                    player2Devices.Add(newGamepad);
                    SetupDeviceFilters();
                    Debug.Log($"Gamepad reconectado a Player2");
                    return;
                }

                // Si es el gamepad de Player1
                if (player1Gamepad != null && AreGamepadsSame(newGamepad, player1Gamepad))
                {
                    player1Gamepad = newGamepad;
                    player1Devices.Remove(device); // Remover versión vieja
                    player1Devices.Add(newGamepad);
                    SetupDeviceFilters();
                    Debug.Log($"Gamepad reconectado a Player1");
                    return;
                }

                // Nuevo gamepad
                if (player2Gamepad == null)
                {
                    player2Gamepad = newGamepad;
                    player2Devices.Add(newGamepad);
                    SetupDeviceFilters();
                    player2Script.SetUIType(true);
                    Debug.Log($"Gamepad asignado a Player2");
                }
                else if (player1Gamepad == null)
                {
                    player1Gamepad = newGamepad;
                    player1Devices.Add(newGamepad);
                    SetupDeviceFilters();
                    player1Script.SetUIType(true);
                    Debug.Log($"Gamepad asignado a Player1");
                }
                break;

            case InputDeviceChange.Removed:
            case InputDeviceChange.Disconnected:
                // Remover de los sets pero mantener la referencia para reconocer al reconectar
                if (player2Devices.Contains(device))
                {
                    player2Devices.Remove(device);
                    if (device == player2Gamepad)
                    {
                        player2Script.SetUIType(false);
                    }
                    SetupDeviceFilters();
                    Debug.Log($"Gamepad removido de Player2");
                }
                else if (player1Devices.Contains(device))
                {
                    player1Devices.Remove(device);
                    if (device == player1Gamepad)
                    {
                        player1Script.SetUIType(false);
                    }
                    SetupDeviceFilters();
                    Debug.Log($"Gamepad removido de Player1");
                }
                break;
        }
    }

    private bool AreGamepadsSame(Gamepad a, Gamepad b)
    {
        return a.description.manufacturer == b.description.manufacturer &&
               a.description.product == b.description.product &&
               a.description.serial == b.description.serial;
    }

    private void OnDestroy()
    {
        InputSystem.onDeviceChange -= OnDeviceChange;
    }
}

using UnityEngine;
using UnityEngine.InputSystem;
using System.Collections.Generic;

public class InputDeviceManager : MonoBehaviour
{
    [SerializeField] private PlayerInput player1;
    [SerializeField] private PlayerInput player2;

    private Gamepad player1Gamepad = null;
    private Gamepad player2Gamepad = null;

    private HashSet<InputDevice> player1Devices = new HashSet<InputDevice>();
    private HashSet<InputDevice> player2Devices = new HashSet<InputDevice>();

    private Player player1Script;
    private Player player2Script;

    void Awake()
    {
        // Crear instancias separadas de ActionAssets
        player1.actions = Instantiate(player1.actions);
        player2.actions = Instantiate(player2.actions);

        player1Script = player1.GetComponent<Player>();
        player2Script = player2.GetComponent<Player>();

        // Deshabilitar el auto-switching
        player1.neverAutoSwitchControlSchemes = true;
        player2.neverAutoSwitchControlSchemes = true;

        // Asignar dispositivos iniciales
        if (Keyboard.current != null)
        {
            player1Devices.Add(Keyboard.current);
        }

        if (Gamepad.all.Count > 0)
        {
            player2Gamepad = Gamepad.all[0];
            player2Devices.Add(player2Gamepad);
            player2Devices.Add(Keyboard.current);
        }
        if (Gamepad.all.Count > 1)
        {
            player1Gamepad = Gamepad.all[1];
            player1Devices.Add(player1Gamepad);
        }

        // Configurar filtros de dispositivos
        SetupDeviceFilters();

        // Set initial UI types
        player1Script.SetUIType(player1Gamepad != null);
        player2Script.SetUIType(player2Gamepad != null);

        // Habilitar acciones
        player1.actions.Enable();
        player2.actions.Enable();

        // Suscribirse a cambios de dispositivos
        InputSystem.onDeviceChange += OnDeviceChange;
    }

    private void SetupDeviceFilters()
    {
        // Convertir HashSet a lista para Player1
        var p1DeviceList = new List<InputDevice>(player1Devices);
        if (p1DeviceList.Count > 0)
        {
            player1.actions.devices = new UnityEngine.InputSystem.Utilities.ReadOnlyArray<InputDevice>(p1DeviceList.ToArray());
        }

        // Convertir HashSet a lista para Player2
        var p2DeviceList = new List<InputDevice>(player2Devices);
        if (p2DeviceList.Count > 0)
        {
            player2.actions.devices = new UnityEngine.InputSystem.Utilities.ReadOnlyArray<InputDevice>(p2DeviceList.ToArray());
        }

        Debug.Log($"Player1 devices: {player1Devices.Count}");
        Debug.Log($"Player2 devices: {player2Devices.Count}");
    }

    private void OnDeviceChange(InputDevice device, InputDeviceChange change)
    {
        if (!(device is Gamepad newGamepad))
            return;

        switch (change)
        {
            case InputDeviceChange.Added:
            case InputDeviceChange.Reconnected:
                // Si es el gamepad de Player2
                if (player2Gamepad != null && AreGamepadsSame(newGamepad, player2Gamepad))
                {
                    player2Gamepad = newGamepad;
                    player2Devices.Remove(device); // Remover versión vieja
                    player2Devices.Add(newGamepad);
                    SetupDeviceFilters();
                    player2Script.SetUIType(true);
                    Debug.Log($"Gamepad reconectado a Player2");
                    return;
                }

                // Si es el gamepad de Player1
                if (player1Gamepad != null && AreGamepadsSame(newGamepad, player1Gamepad))
                {
                    player1Gamepad = newGamepad;
                    player1Devices.Remove(device); // Remover versión vieja
                    player1Devices.Add(newGamepad);
                    SetupDeviceFilters();
                    player1Script.SetUIType(true);
                    Debug.Log($"Gamepad reconectado a Player1");
                    return;
                }

                // Nuevo gamepad
                if (player2Gamepad == null)
                {
                    player2Gamepad = newGamepad;
                    player2Devices.Add(newGamepad);
                    SetupDeviceFilters();
                    player2Script.SetUIType(true);
                    Debug.Log($"Gamepad asignado a Player2");
                }
                else if (player1Gamepad == null)
                {
                    player1Gamepad = newGamepad;
                    player1Devices.Add(newGamepad);
                    SetupDeviceFilters();
                    player1Script.SetUIType(true);
                    Debug.Log($"Gamepad asignado a Player1");
                }
                break;

            case InputDeviceChange.Removed:
            case InputDeviceChange.Disconnected:
                // Remover de los sets pero mantener la referencia para reconocer al reconectar
                if (player2Devices.Contains(device))
                {
                    player2Devices.Remove(device);
                    if (device == player2Gamepad)
                    {
                        player2Script.SetUIType(false);
                    }
                    SetupDeviceFilters();
                    Debug.Log($"Gamepad removido de Player2");
                }
                else if (player1Devices.Contains(device))
                {
                    player1Devices.Remove(device);
                    if (device == player1Gamepad)
                    {
                        player1Script.SetUIType(false);
                    }
                    SetupDeviceFilters();
                    Debug.Log($"Gamepad removido de Player1");
                }
                break;
        }
    }

    private bool AreGamepadsSame(Gamepad a, Gamepad b)
    {
        return a.description.manufacturer == b.description.manufacturer &&
               a.description.product == b.description.product &&
               a.description.serial == b.description.serial;
    }

    private void OnDestroy()
    {
        InputSystem.onDeviceChange -= OnDeviceChange;
    }
}
